import json

def try_hypothesis(hypothesis, rows=9, cols=27, yellow_row=4, orig_r=1, orig_c_start=16, orig_c_end=20):
    output_grid = [[1 for _ in range(cols)] for _ in range(rows)]

    # Set yellow row
    for c in range(cols):
        output_grid[yellow_row][c] = 2

    # Apply hypothesis
    if hypothesis == 'original':
        for c in range(orig_c_start, orig_c_end):
            output_grid[orig_r][c] = 3
    elif hypothesis == 'horz_mirror':
        for c in range(orig_c_start, orig_c_end):
            new_c = cols - 1 - c
            output_grid[orig_r][new_c] = 3
    elif hypothesis == 'vert_mirror':
        for c in range(orig_c_start, orig_c_end):
            new_r = 2 * yellow_row - orig_r
            output_grid[new_r][c] = 3
    elif hypothesis == 'both_mirror':
        for c in range(orig_c_start, orig_c_end):
            new_r = 2 * yellow_row - orig_r
            new_c = cols - 1 - c
            output_grid[new_r][new_c] = 3
    elif hypothesis == 'horz_only_short':
        for c in range(orig_c_start, orig_c_end):
            new_c = cols - 1 - c  # Right-center
            # But the actual mirror center might be different - let's use col 13
            new_c = 2 * 13 - c  # Center of 0-26 is 13
            output_grid[orig_r][new_c] = 3
    elif hypothesis == 'vert_only_short':
        for c in range(orig_c_start, orig_c_end):
            new_r = 2 * 4 - orig_r  # Center of 0-8 is 4
            output_grid[new_r][c] = 3

    return output_grid

